-- Queue Management (A4, Asad). One Queue row per Service; one QueueEntry row per join.
-- Position is never stored: it changes whenever someone ahead leaves or is served, so it is
-- computed from ("priorityRank" DESC, "entryId" ASC) -- the same rule as A3.
CREATE TABLE IF NOT EXISTS "Queue" (
  "queueId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "serviceId" INTEGER NOT NULL UNIQUE REFERENCES "Service" ("serviceId"),
  status VARCHAR(6) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- "userId" has no foreign key yet: UserCredentials is still in memory (Member 1).
-- When that table exists, add: FOREIGN KEY ("userId") REFERENCES "UserCredentials" ("userId").
CREATE TABLE IF NOT EXISTS "QueueEntry" (
  "entryId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "queueId" INTEGER NOT NULL REFERENCES "Queue" ("queueId"),
  "userId" INTEGER NOT NULL CHECK ("userId" > 0),
  "priorityRank" SMALLINT NOT NULL CHECK ("priorityRank" BETWEEN 1 AND 3),
  status VARCHAR(8) NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'served', 'canceled')),
  "joinedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "endedAt" TIMESTAMPTZ,
  "almostReadyNotified" BOOLEAN NOT NULL DEFAULT FALSE,
  CHECK ((status = 'waiting') = ("endedAt" IS NULL))
);

-- The database itself guarantees a user is waiting in at most one queue.
CREATE UNIQUE INDEX IF NOT EXISTS queue_entry_one_waiting_per_user
  ON "QueueEntry" ("userId") WHERE status = 'waiting';
CREATE INDEX IF NOT EXISTS queue_entry_order
  ON "QueueEntry" ("queueId", "priorityRank" DESC, "entryId") WHERE status = 'waiting';
CREATE INDEX IF NOT EXISTS queue_entry_user ON "QueueEntry" ("userId", "entryId" DESC);
